};

export function TeamSimple({
  id,
  title,
  description = "",
  members,
  level = 2,
  padding = "standard",
  align = "center",
  cols = "3",
  surface = "plain",
  landmarkLabel,
}: TeamSimpleProps) {
  const titleId = id + "-title";
